def test_get_account_transfers_returns_debit_and_credit_transfers_for_an_account(client):
    account_1_id = tb.id()
    account_2_id = tb.id()
    account_3_id = tb.id()
    debit_transfer_id = tb.id()
    credit_transfer_id = tb.id()
    client.create_accounts(
        [
            tb.Account(
                id=account_1_id,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=account_2_id,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=account_3_id,
                ledger=1,
                code=1,
            ),
        ]
    )
    client.create_transfers(
        [
            tb.Transfer(
                id=debit_transfer_id,
                debit_account_id=account_1_id,
                credit_account_id=account_2_id,
                amount=10,
                ledger=1,
                code=1,
            ),
            tb.Transfer(
                id=credit_transfer_id,
                debit_account_id=account_3_id,
                credit_account_id=account_1_id,
                amount=20,
                ledger=1,
                code=1,
            ),
        ]
    )
    transfers = client.get_account_transfers(
        tb.AccountFilter(
            account_id=account_1_id,
            user_data_128=0,
            user_data_64=0,
            user_data_32=0,
            code=0,
            timestamp_min=0,
            timestamp_max=0,
            limit=10,
            flags=tb.AccountFilterFlags.DEBITS | tb.AccountFilterFlags.CREDITS,
        )
    )
    assert len(transfers) == 2
    assert transfers[0].id == debit_transfer_id
    assert transfers[0].amount == 10
    assert transfers[1].id == credit_transfer_id
    assert transfers[1].amount == 20

